def _to_delimited(rows: list, delimiter: str) -> str:
    if not rows:
        return ""
    out = io.StringIO()
    writer = csv.DictWriter(out, fieldnames=list(rows[0]), delimiter=delimiter)
    writer.writeheader()
    writer.writerows(rows)
    return out.getvalue()


def to_csv(rows: list) -> str:
    return _to_delimited(rows, ",")


def to_tsv(rows: list) -> str:
    return _to_delimited(rows, "\t")

